def articulation_points(graph, n):
    timer = 0
    tin = [-1] * n
    low = [-1] * n
    is_cut = [False] * n

    def dfs(u, parent):
        nonlocal timer
        tin[u] = low[u] = timer
        timer += 1
        children = 0

        for v in graph[u]:
            if v == parent:
                continue

            if tin[v] != -1:
                low[u] = min(low[u], tin[v])
            else:
                dfs(v, u)
                low[u] = min(low[u], low[v])

                if parent != -1 and low[v] >= tin[u]:
                    is_cut[u] = True
                children += 1

        if parent == -1 and children > 1:
            is_cut[u] = True

    for i in range(n):
        if tin[i] == -1:
            dfs(i, -1)

    return [i for i in range(n) if is_cut[i]]

